 CREATE OR REPLACE FUNCTION public.createmanualinvestigation(datypeid uuid, dasubtypeid uuid, v_investigationid uuid, securityuserid character varying, v_roletypecode character varying DEFAULT 'CW'::character varying, v_teamtypekey character varying DEFAULT 'CW'::character varying)   
  RETURNS character varying                                                                                                                                                                                                                                                                  
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                           
 AS $function$                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                             
 DECLARE                                                                                                                                                                                                                                                                                     
 v_activity  record;                                                                                                                                                                                                                                                                         
 newactivityid  uuid;                                                                                                                                                                                                                                                                        
 duedate  timestamp;                                                                                                                                                                                                                                                                         
 v_intakeserviceid  uuid;                                                                                                                                                                                                                                                                    
 l_count  bigint;                                                                                                                                                                                                                                                                            
 v_teamtypekey  character  varying;                                                                                                                                                                                                                                                          
 v_addtaskcount  bigint;                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                             
 BEGIN                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                             
 duedate:=now();                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                             
                 SELECT  inv.intakeserviceid  INTO  v_intakeserviceid  FROM  investigation  inv                                                                                                                                                                                              
                 WHERE  inv.investigationid  =  v_investigationid  AND  inv.activeflag  =  1;                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                             
                 SELECT  inr.teamtypekey  INTO  v_teamtypekey  FROM  intakeservicerequest  inr                                                                                                                                                                                               
                 WHERE  inr.intakeserviceid  =  v_intakeserviceid  AND  inr.activeflag  =  1;                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                             
         IF  v_teamtypekey  =  'CW'  THEN                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                             
                 SELECT    COUNT(1)  INTO  l_count                                                                                                                                                                                                                                           
                 FROM  intakeservicerequestactor  isr                                                                                                                                                                                                                                        
                 INNER  JOIN  person  ps  ON  isr.personid  =  ps.personid  AND  ps.activeflag  =1                                                                                                                                                                                           
                 WHERE  isr.intakeserviceid    =v_intakeserviceid                                                                                                                                                                                                                            
                 AND  ps.dateofdeath  IS  NOT  NULL                                                                                                                                                                                                                                          
                 AND  isr.intakeservicerequestpersontypekey  IN  ('RC')                                                                                                                                                                                                                      
                 AND  isr.isprimary  =  true;                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                             
                 IF  COALESCE  (l_count,0)  >  0  THEN                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                             
                           SELECT  COUNT(1)  INTO    v_addtaskcount                                                                                                                                                                                                                          
                           FROM    activitytask  at                                                                                                                                                                                                                                          
                           INNER  JOIN      ammappingtask  amt  ON  at.amtaskid  =  amt.amtaskid  AND  amt.required  =true                                                                                                                                                                   
                           AND    amt.ismandatory_fatality  =1      AND  amt.activeflag  =1                                                                                                                                                                                                  
                           INNER  JOIN    activity  a  ON  a.ammappingid    =  amt.ammappingid  AND  a.activityid  =  at.activityid                                                                                                                                                          
                             AND  a.activeflag  =1  AND  a.objectid  =  v_investigationid                                                                                                                                                                                                    
                           WHERE  at.activeflag  =1;                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                             
                         IF  COALESCE  (v_addtaskcount,0)  =  0  THEN                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                             
                                 FOR  v_activity  IN                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                             
                                         SELECT    am.name,        am.amactivityid,                                                                                                                                                                                                          
                                                         am.ammappingid,v_investigationid,am.description,                                                                                                                                                                                    
                                                         am.activitytypekey,  am.helptext                                                                                                                                                                                                    
                                         FROM  investigationmapping  AS  im                                                                                                                                                                                                                  
                                         INNER  JOIN  servicerequesttypeconfig  as  sc  ON  sc.servicerequesttypeconfigid  =  im.objectid                                                                                                                                                    
                                         INNER  JOIN  ammapping  am  ON  am.ammappingid  =  im.ammappingid  AND  am.activitytypekey  ='Investigation'AND  am.teamtypekey  =v_teamtypekey  AND  coalesce(am.isinvestigstionactivity,0)  =1                                                    
                                         INNER  JOIN  ammappingrole  amr  on  amr.ammappingid  =  am.ammappingid  AND  amr.activeflag  =1  AND  amr.roletypecode  =v_roletypecode                                                                                                            
                                         INNER  JOIN  (  SELECT  distinct  ammappingid  from  (SELECT  distinct  ammappingid  FROM  ammappingtask  amt                                                                                                                                       
                                                                 INNER  JOIN  activitytasktype  ats  on  ats.activitytasktypekey  =  amt.activitytasktypekey                                                                                                                                 
                                                                 AND  amt.activeflag  =1  and  ats.activeflag  =1                                                                                                                                                                            
                                                                 AND  ats.activitytypekey  ='Investigation'                                                                                                                                                                                  
                                                                 AND  amt.required  =true                                                                                                                                                                                                    
                                                                 AND  amt.ismandatory_fatality  =1                                                                                                                                                                                           
                                                 )  as  t                                                                                                                                                                                                                                    
                                                 )  as  amt                                                                                                                                                                                                                                  
                                         ON  amt.ammappingid  =  am.ammappingid                                                                                                                                                                                                              
                                         WHERE  coalesce(im.isreviewactivity  ,false)    =false                                                                                                                                                                                              
                                         AND  sc.intakeservreqtypeid  in  (datypeid)                                                                                                                                                                                                         
                                         AND  sc.servicerequestsubtypeid  in  (dasubtypeid)                                                                                                                                                                                                  
                                         AND  sc.activeflag    =1                                                                                                                                                                                                                            
                                         AND  sc.intakeservicerequestplantypekey='INV'                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                             
                                 LOOP                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                             
                                         INSERT  INTO  activity                                                                                                                                                                                                                              
                                                         (                                                                                                                                                                                                                                   
                                                         description,    amactivityid                                                                                                                                                                                                        
                                                         ,ammappingid,objectid,sourcedescription                                                                                                                                                                                             
                                                         ,activitytypekey,helptext,sequence                                                                                                                                                                                                  
                                                         ,updatedby,insertedby                                                                                                                                                                                                               
                                                         ,effectivedate,expirationdate                                                                                                                                                                                                       
                                                 )                                                                                                                                                                                                                                           
                                         VALUES                                                                                                                                                                                                                                              
                                                 (                                                                                                                                                                                                                                           
                                                 v_activity.name,    v_activity.amactivityid,                                                                                                                                                                                                
                                                 v_activity.ammappingid,  v_investigationid,  v_activity.description,                                                                                                                                                                        
                                                 v_activity.activitytypekey,  v_activity.helptext,  1,                                                                                                                                                                                       
                                                 securityuserid,securityuserid,  now(),duedate)  RETURNING  "activityid"  INTO    newactivityid;                                                                                                                                             
                                                                                                                                                                                                                                                                                             
         /*ACTIVIY  TASK  taken  from  activity  mapping  based  on  mapping  id    (task  status  hardcoded)*/                                                                                                                                                                              
                                                                                                                                                                                                                                                                                             
                                         INSERT  INTO    activitytask                                                                                                                                                                                                                        
                                                 (                                                                                                                                                                                                                                           
                                                   activityid,name,description                                                                                                                                                                                                               
                                                 ,helptext,amtaskid,assignedto                                                                                                                                                                                                               
                                                 ,assignedon  ,activitytaskstatustypekey                                                                                                                                                                                                     
                                                 ,activitytasktypekey,activityprioritytypekey,duedate                                                                                                                                                                                        
                                                 ,sequence,required,activeflag                                                                                                                                                                                                               
                                                 ,updatedby,insertedby,EffectiveDate                                                                                                                                                                                                         
                                                 ,assessmenttemplateid                                                                                                                                                                                                                       
                                                 )                                                                                                                                                                                                                                           
                                         SELECT    newactivityid  ,ta.name,  ta.description,                                                                                                                                                                                                 
                                                 am.helptext,ta.amtaskid,securityuserid,                                                                                                                                                                                                     
                                                 now()  at  time  zone  'utc'  ,'InvOpen',                                                                                                                                                                                                   
                                                 amt.activitytasktypekey,  amt.activityprioritytypekey,                                                                                                                                                                                      
                                                 (now()  at  time  zone  'utc'  )::  date    +coalesce(amt.duedateoffset,1)                                                                                                                                                                  
                                                 ,1,true,1,                                                                                                                                                                                                                                  
                                                 securityuserid,securityuserid,  now()  at  time  zone  'utc'                                                                                                                                                                                
                                                 ,amt.assessmenttemplateid                                                                                                                                                                                                                   
                                         FROM  investigationmapping  as  im                                                                                                                                                                                                                  
                                         INNER  JOIN  servicerequesttypeconfig  as  sc  ON  sc.servicerequesttypeconfigid  =  im.objectid                                                                                                                                                    
                                         INNER  JOIN  ammapping  am  ON  am.ammappingid  =  im.ammappingid  AND  am.activitytypekey  ='Investigation'                                                                                                                                        
                                         INNER  JOIN    ammappingtask  amt      ON  amt.ammappingid  =  am.ammappingid                                                                                                                                                                       
                                         INNER  JOIN  activitytasktype  ats  ON  ats.activitytasktypekey  =  amt.activitytasktypekey  AND  amt.activeflag  =1  AND  ats.activeflag  =1  AND  ats.activitytypekey  ='Investigation'AND  amt.required  =true  AND  amt.ismANDatory_fatality  =1
                                         INNER  JOIN  amtask  ta  on  ta.amtaskid  =  amt.amtaskid  AND  ta.activeflag  =1  AND  ats.activeflag  =1  AND  ta.activitytypekey  ='Investigation'                                                                                               
                                         WHERE  sc.intakeservreqtypeid  in  (datypeid)                                                                                                                                                                                                       
                                         AND  sc.servicerequestsubtypeid  in  (dasubtypeid)                                                                                                                                                                                                  
                                         AND  sc.activeflag    =1                                                                                                                                                                                                                            
                                         AND  sc.intakeservicerequestplantypekey='INV'                                                                                                                                                                                                       
                                         AND  am.ammappingid  =v_activity.ammappingid;                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                             
                                 END  LOOP;                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                             
                         END  IF;                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                             
                 ELSE                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                             
                       UPDATE  activitytask  SET  activeflag  =0  FROM  activitytask  at                                                                                                                                                                                                     
                                                               INNER  JOIN    ammappingtask  amt  ON  amt.amtaskid    =  at.amtaskid    AND  amt.activeflag  =1                                                                                                                              
                                                                 AND  amt.required  =true  AND    amt.ismandatory_fatality  =1                                                                                                                                                               
                                                               INNER  JOIN    activity  a  ON  a.ammappingid    =  amt.ammappingid                                                                                                                                                           
                                                                 AND  a.activityid  =  at.activityid                                                                                                                                                                                         
                                                                 AND  a.activeflag  =1  AND  a.objectid  =  v_investigationid                                                                                                                                                                
                                                               WHERE  at.activeflag  =1    AND  activitytask.activitytaskID  =  at.activitytaskID  ;                                                                                                                                         
                                                                                                                                                                                                                                                                                             
                 END  IF;                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                             
         END  IF;                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                             
 RETURN                                                                                                                                                                                                                                                                                      
           'Success';                                                                                                                                                                                                                                                                        
 END;                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                             
 $function$                                                                                                                                                                                                                                                                                  

